<script lang="ts">
  import { invoke, isTauri } from '@tauri-apps/api/core'; import { onMount } from 'svelte';
  type Source={id:string;publisher:string;url:string;enabled:boolean;minimumPollSeconds:number;termsOwner:string;reviewReference:string;validUntil:string;retainRawPayload:boolean;allowMetadataRedistribution:boolean;version:number;recordedAt:string};
  type Runtime={sourceId:string;policyVersion:number;state:string;lastAttemptAt:string|null;lastSuccessAt:string|null;nextAttemptAt:string;consecutiveFailures:number;statusCode:number|null;bytesReceived:number;message:string};
  let sources=$state<Source[]>([]);let search=$state('');let sort=$state('publisher');let editing=$state(false);let busy=$state(false);let error=$state('');let importText=$state('');
  let runtime=$state<Record<string,Runtime>>({});let running=$state(false);
  let probe=$state<{status:number;mediaType?:string;bytesReceived:number;checkedAt:string;message:string}|null>(null);
  const importExample='[{"id":"publisher-feed","publisher":"Publisher","url":"https://example.com/feed.xml","enabled":false}]';
  let draft=$state({id:'',publisher:'',url:'https://',enabled:false,minimumPollSeconds:900,termsOwner:'',reviewReference:'',validUntil:new Date(Date.now()+365*86400000).toISOString(),retainRawPayload:false,allowMetadataRedistribution:false});
  const filtered=$derived(sources.filter(source=>`${source.publisher} ${source.id} ${source.url} ${source.termsOwner}`.toLowerCase().includes(search.toLowerCase())).toSorted((a,b)=>sort==='cadence'?a.minimumPollSeconds-b.minimumPollSeconds:sort==='status'?Number(b.enabled)-Number(a.enabled):a.publisher.localeCompare(b.publisher)));
  async function load(){if(isTauri()){sources=await invoke<Source[]>('list_feed_sources');const rows=await invoke<Runtime[]>('feed_runtime_status');runtime=Object.fromEntries(rows.map(row=>[row.sourceId,row]));}}
  async function runScheduler(){running=true;error='';try{await invoke<Runtime[]>('run_feed_scheduler_once');await load()}catch(cause){error=String(cause)}finally{running=false}}
  function edit(source?:Source){draft=source?{id:source.id,publisher:source.publisher,url:source.url,enabled:source.enabled,minimumPollSeconds:source.minimumPollSeconds,termsOwner:source.termsOwner,reviewReference:source.reviewReference,validUntil:source.validUntil,retainRawPayload:source.retainRawPayload,allowMetadataRedistribution:source.allowMetadataRedistribution}:{id:'',publisher:'',url:'https://',enabled:false,minimumPollSeconds:900,termsOwner:'',reviewReference:'',validUntil:new Date(Date.now()+365*86400000).toISOString(),retainRawPayload:false,allowMetadataRedistribution:false};error='';probe=null;editing=true;}
  async function save(){busy=true;error='';try{await invoke('upsert_feed_source',{source:{...draft,minimumPollSeconds:Number(draft.minimumPollSeconds)}});editing=false;await load()}catch(cause){error=String(cause)}finally{busy=false}}
  async function importBatch(){busy=true;error='';try{const parsed=JSON.parse(importText);if(!Array.isArray(parsed))throw new Error('Import must be a JSON array.');await invoke('import_feed_sources',{sources:parsed});importText='';await load()}catch(cause){error=String(cause)}finally{busy=false}}
  async function testFeed(){busy=true;error='';probe=null;try{probe=await invoke('test_feed_source',{sourceId:draft.id})}catch(cause){error=String(cause)}finally{busy=false}}
  onMount(()=>{void load();const timer=setInterval(()=>void load(),15000);return()=>clearInterval(timer)});
</script>
<svelte:head><title>Feed control · PRISMATIK</title></svelte:head>
<div class="feeds"><header><div><span>RSS / ATOM INTELLIGENCE CONTROL</span><h1>Attention mesh</h1><p>Register thousands of publisher-provided feeds through reviewed source policies. The durable scheduler performs real conditional HTTPS acquisition with restart-safe checkpoints and backoff; parsing remains visibly inactive until its dependency is approved.</p></div><div class="head-actions"><button onclick={runScheduler} disabled={running}>{running?'RUNNING…':'RUN DUE SOURCES'}</button><button onclick={()=>edit()}>REGISTER SOURCE</button></div></header>
  <section class="stats"><article><span>REGISTERED</span><b>{sources.length}</b><p>Latest policy versions</p></article><article><span>ENABLED</span><b>{sources.filter(source=>source.enabled).length}</b><p>Admitted to durable scheduler</p></article><article><span>FETCHED</span><b>{Object.values(runtime).filter(row=>row.lastSuccessAt).length}</b><p>Real conditional checkpoints</p></article><article><span>PARSER</span><b>GATED</b><p>Fetched bodies are not retained or analyzed</p></article></section>
  <section class="controls"><input bind:value={search} placeholder="Search publisher, source, URL or owner"/><select bind:value={sort}><option value="publisher">Sort: publisher</option><option value="cadence">Sort: cadence</option><option value="status">Sort: status</option></select></section>
  <section class="table"><div class="row head"><span>Source</span><span>Policy</span><span>Cadence</span><span>Retention</span><span>Runtime</span></div>{#each filtered as source}{@const health=runtime[source.id]}<button class="row" onclick={()=>edit(source)}><span><b>{source.publisher}</b><small>{source.id}<br/>{source.url}</small></span><span><b>v{source.version}</b><small>{source.termsOwner}<br/>{source.reviewReference}</small></span><span><b>{source.minimumPollSeconds}s</b><small>valid until {source.validUntil.slice(0,10)}</small></span><span><b>{source.retainRawPayload?'RAW ALLOWED':'METADATA ONLY'}</b><small>{source.allowMetadataRedistribution?'metadata redistribution':'local only'}</small></span><span class:enabled={health?.state==='fetched_unparsed'||health?.state==='not_modified'} class:failed={health?.state==='backoff'}>{health?.state?.replaceAll('_',' ').toUpperCase()??(source.enabled?'QUEUED':'DISABLED')}<small>{health?.lastAttemptAt?`last ${new Date(health.lastAttemptAt).toLocaleTimeString()} · next ${new Date(health.nextAttemptAt).toLocaleTimeString()}`:'No acquisition attempt'}</small></span></button>{:else}<div class="empty">No reviewed feed sources registered.</div>{/each}</section>
  <details><summary>BATCH IMPORT · UP TO 10,000 REVIEWED RECORDS</summary><p>Every entry is validated before any record is appended. Required camelCase fields match the registration form.</p><textarea rows="7" bind:value={importText} placeholder={importExample}></textarea>{#if error&&!editing}<p class="error">{error}</p>{/if}<button onclick={importBatch} disabled={busy||!importText.trim()}>VALIDATE & APPEND BATCH</button></details>
</div>
{#if editing}<button class="scrim" aria-label="Close" onclick={()=>editing=false}></button><dialog open><h2>Reviewed source policy</h2><div class="form"><label>Stable source ID<input bind:value={draft.id}/></label><label>Publisher<input bind:value={draft.publisher}/></label><label class="wide">Canonical HTTPS feed URL<input bind:value={draft.url}/></label><label>Minimum poll seconds<input type="number" min="60" max="604800" bind:value={draft.minimumPollSeconds}/></label><label>Valid until (RFC3339)<input bind:value={draft.validUntil}/></label><label>Terms owner<input bind:value={draft.termsOwner}/></label><label>Review reference<input bind:value={draft.reviewReference}/></label><label class="check"><input type="checkbox" bind:checked={draft.enabled}/>Enable for scheduler admission</label><label class="check"><input type="checkbox" bind:checked={draft.retainRawPayload}/>Raw payload retention authorized</label><label class="check"><input type="checkbox" bind:checked={draft.allowMetadataRedistribution}/>Metadata redistribution authorized</label></div>{#if error}<p class="error">{error}</p>{/if}{#if probe}<div class="probe"><b>HTTP {probe.status} · {probe.bytesReceived.toLocaleString()} bytes · {probe.mediaType??'unknown type'}</b><p>{probe.message}</p><small>{probe.checkedAt}</small></div>{/if}<footer><button onclick={()=>editing=false}>CANCEL</button>{#if sources.some(source=>source.id===draft.id)}<button onclick={testFeed} disabled={busy}>TEST REAL FEED</button>{/if}<button onclick={save} disabled={busy}>{busy?'VALIDATING…':'APPEND POLICY VERSION'}</button></footer></dialog>{/if}
<style>
.feeds{height:100%;overflow:auto;padding:34px clamp(22px,3vw,48px) 80px;color:var(--p-text)}header{display:flex;justify-content:space-between;gap:24px;align-items:end}header span{font:600 .6rem var(--font-mono);letter-spacing:.14em;color:var(--p-accent)}h1{font-size:clamp(2.8rem,5vw,5.5rem);letter-spacing:-.07em;margin:8px 0}header p{max-width:850px;color:var(--p-dim);line-height:1.55}button{cursor:pointer}header button,details button{border:0;background:var(--p-accent);color:var(--p-bg);padding:11px 15px;font:700 .6rem var(--font-mono)}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:24px 0}.stats article{border:1px solid var(--p-border);background:var(--p-panel-fill);padding:16px}.stats span{font:.55rem var(--font-mono);color:var(--p-dim)}.stats b{display:block;margin:8px 0;font:1.2rem var(--font-mono)}.stats p{margin:0;color:var(--p-dim);font-size:.68rem}.controls{display:flex;gap:10px;margin-bottom:10px}.controls input{flex:1}.controls input,.controls select,dialog input,details textarea{border:1px solid var(--p-border);background:var(--p-surface2);color:var(--p-text);padding:10px}.table{border:1px solid var(--p-border)}.row{display:grid;grid-template-columns:1.4fr 1fr .7fr .8fr .5fr;gap:12px;width:100%;padding:13px;border:0;border-bottom:1px solid var(--p-border);background:var(--p-panel-fill);color:var(--p-text);text-align:left}.row.head{font:.56rem var(--font-mono);color:var(--p-dim)}button.row:hover{background:var(--p-surface2)}.row b,.row small{display:block}.row b{font-size:.72rem}.row small{margin-top:5px;color:var(--p-dim);font-size:.62rem;line-height:1.4;overflow-wrap:anywhere}.row>span:last-child{font:.56rem var(--font-mono);color:#ffcb7b}.row>span.enabled{color:#67efba}.empty{padding:45px;text-align:center;color:var(--p-dim)}details{margin-top:12px;border:1px solid var(--p-border);padding:16px}summary{font:.62rem var(--font-mono);color:var(--p-accent);cursor:pointer}details p{color:var(--p-dim)}details textarea{width:100%;display:block;margin:10px 0;font-family:var(--font-mono)}.scrim{position:fixed;inset:0;z-index:80;border:0;background:#000a}dialog{position:fixed;z-index:81;inset:50% auto auto 50%;transform:translate(-50%,-50%);width:min(720px,calc(100vw - 30px));max-height:90vh;overflow:auto;border:1px solid var(--p-border);background:var(--p-surface);color:var(--p-text);padding:22px}.form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.form label{display:grid;gap:5px;color:var(--p-dim);font-size:.68rem}.form .wide{grid-column:1/-1}.form .check{display:flex;align-items:center;gap:8px}.form .check input{width:auto}.probe{margin-top:12px;border:1px solid #28e7a455;padding:12px}.probe b{color:#67efba}.probe p,.probe small{color:var(--p-dim)}dialog footer{display:flex;justify-content:flex-end;gap:8px;margin-top:18px}dialog footer button{padding:10px;border:1px solid var(--p-border);background:transparent;color:var(--p-text);font:.6rem var(--font-mono)}dialog footer button:last-child{background:var(--p-accent);color:var(--p-bg)}.error{color:#ff637d}@media(max-width:900px){.stats{grid-template-columns:repeat(2,1fr)}.row{grid-template-columns:1fr 1fr}.row.head{display:none}}@media(max-width:600px){header{display:block}header button{margin-top:10px}.stats,.form{grid-template-columns:1fr}.form .wide{grid-column:auto}}
.head-actions{display:flex;gap:8px}.head-actions button:first-child{border:1px solid var(--p-border);background:var(--p-panel-fill);color:var(--p-accent)}button:disabled{cursor:not-allowed;opacity:.5}.row>span.failed{color:#ff637d}
</style>
